-- 003 · Studio de workflow v2 (canvas) : condition, détails, bannière de run
-- Idempotent : peut être rejoué sans erreur.
-- Prérequis : 001 et 002 exécutés (tables workflows, workflow_nodes, 3 lignes workflows).

ALTER TABLE workflow_nodes DROP CONSTRAINT IF EXISTS workflow_nodes_kind_check;
ALTER TABLE workflow_nodes
  ADD CONSTRAINT workflow_nodes_kind_check
  CHECK (kind IN ('agent','merge','approval','action','condition'));

ALTER TABLE workflow_nodes ADD COLUMN IF NOT EXISTS design_note text;
ALTER TABLE workflow_nodes ADD COLUMN IF NOT EXISTS blurb text;
ALTER TABLE workflow_nodes ADD COLUMN IF NOT EXISTS details jsonb DEFAULT '{}'::jsonb;

ALTER TABLE workflows ADD COLUMN IF NOT EXISTS cost_unit text DEFAULT 'run';
ALTER TABLE workflows ADD COLUMN IF NOT EXISTS run_banner jsonb;

